// ============================================================
// Carrier indices
// ============================================================
// Index into a `schema-graph`'s `type-nodes` list.
type TypeNodeIndex = int32

// Index into a `schema-value-tree`'s `value-nodes` list.
type ValueNodeIndex = int32

// Index into a `schema-graph`'s `defs` list.
type DefIndex = int32

// Stable, language-independent identifier for a named type definition.
// Must be unique within the enclosing `schema-graph`. Conventional format
// is a dot-separated namespace path (e.g., `"myapp.users.user"`). Each
// SDK provides a default derivation rule (typically based on the local
// language's type name); cross-language interop requires the same
// `type-id` on every side, which users can pin via the SDK's `named`
// attribute.
type TypeId = string

// ============================================================
// Common embedded value types
// ============================================================
type Uuid struct {
	HighBits uint64
	LowBits  uint64
}

type Datetime struct {
	// Seconds since the Unix epoch (UTC).
	Seconds int64
	// Nanoseconds since `seconds`, in `[0, 1_000_000_000)`.
	Nanoseconds uint32
}

type EnvironmentId struct {
	Uuid Uuid
}

// ============================================================
// Platform identifiers
// ============================================================
//
// Platform identifiers used by the schema-native surfaces. Keeping them
// here lets migrated interfaces depend on a single core version.
// Represents a Golem component
type ComponentId struct {
	Uuid Uuid
}

// Represents a Golem agent
type AgentId struct {
	// Identifies the component the agent belongs to
	ComponentId ComponentId
	// String representation of the agent ID (agent type and constructor parameters)
	AgentId string
}

const (
	// An agent. A tool invocation is owned by the agent of its external-tool owner.
	InvocationOwnerAgent uint8 = 0
	// A tool. The runtime does not produce this case yet.
	InvocationOwnerTool uint8 = 1
)

// The owner whose oplog records an invocation
type InvocationOwner struct {
	tag   uint8
	value any
}

func (self InvocationOwner) Tag() uint8 {
	return self.tag
}

func (self InvocationOwner) Agent() AgentId {
	if self.tag != InvocationOwnerAgent {
		panic("tag mismatch")
	}
	return self.value.(AgentId)
}
func (self InvocationOwner) Tool() string {
	if self.tag != InvocationOwnerTool {
		panic("tag mismatch")
	}
	return self.value.(string)
}

func MakeInvocationOwnerAgent(value AgentId) InvocationOwner {
	return InvocationOwner{InvocationOwnerAgent, value}
}
func MakeInvocationOwnerTool(value string) InvocationOwner {
	return InvocationOwner{InvocationOwnerTool, value}
}

// Identifies one invocation. With an agent owner, its text form is `<agent>.<uuid>`, where `<agent>` is the owner's `agent-id` string without the component.
type InvocationId struct {
	Owner InvocationOwner
	Id    Uuid
}

// Represents a Golem account
type AccountId struct {
	Uuid Uuid
}

// Represents a Golem permission card
type CardId struct {
	Uuid Uuid
}

// An index into the persistent log storing all performed operations of an agent
type OplogIndex = uint64

// A promise ID is a value that can be passed to an external Golem API to
// complete that promise from an arbitrary external source, while Golem
// agents can await for this completion.
type PromiseId struct {
	AgentId AgentId
	// Fingerprint of the agent incarnation that created the promise. A deleted and
	// re-created agent keeps its agent ID but gets a new fingerprint, so the promise IDs
	// of the deleted incarnation do not reach the new one.
	Fingerprint Uuid
	OplogIdx    uint64
}

//go:wasmimport golem:core/types@2.0.0 [resource-drop]quota-token
func resourceDropQuotaToken(handle int32)

// ============================================================
// Capability resources
// ============================================================
// An unforgeable capability granting the right to consume a named
// resource. The handle is opaque: a guest can only obtain one from the
// host (e.g. via `golem:quota`) and can never inspect or fabricate its
// internal state. When carried in a `schema-value-tree` (see
// `schema-value-node::quota-token-handle`) the handle is transferred by
// ownership; the host converts it to/from its internal trusted
// representation at the boundary.
type QuotaToken struct {
	handle *witRuntime.Handle
}

func (self *QuotaToken) TakeHandle() int32 {
	return self.handle.Take()
}

func (self *QuotaToken) SetHandle(handle int32) {
	self.handle.Set(handle)
}

func (self *QuotaToken) Handle() int32 {
	return self.handle.Use()
}

func (self *QuotaToken) Drop() {
	handle := self.handle.TakeOrNil()
	if handle != 0 {
		resourceDropQuotaToken(handle)
	}
}

func QuotaTokenFromOwnHandle(handleValue int32) *QuotaToken {
	handle := witRuntime.MakeHandle(handleValue)
	value := &QuotaToken{handle}
	runtime.AddCleanup(value, func(_ int) {
		handleValue := handle.TakeOrNil()
		if handleValue != 0 {
			resourceDropQuotaToken(handleValue)
		}
	}, 0)
	return value
}

func QuotaTokenFromBorrowHandle(handleValue int32) *QuotaToken {
	handle := witRuntime.MakeHandle(handleValue)
	return &QuotaToken{handle}
}

